using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.FNZ.Transacciones;using GraphApi.Services.FNZ.Transacciones;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.FNZ.Transacciones{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Transacciones: creación, actualización y eliminación.")]    public class TransaccionesMutation    {        [Authorize]        [GraphQLName("createTransacciones")]        [GraphQLDescription("Crea un nuevo Transaccione usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTransacciones> CreateTransaccionesAsync(            [GraphQLDescription("Datos necesarios para crear el Transaccione.")]            clCreateTransacciones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Transaccione.")]            ITransaccionesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTransacciones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTransacciones")]        [GraphQLDescription("Actualiza los campos especificados de un Transaccione existente.")]        public async Task<clReadTransacciones?> UpdateTransaccionesAsync(            [GraphQLDescription("Datos del Transaccione a actualizar.")]            clUpdateTransacciones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Transaccione.")]            ITransaccionesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTransacciones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTransacciones")]        [GraphQLDescription("Elimina un Transaccione por su ID.")]        public async Task<bool> delTransaccionesAsync(            [GraphQLDescription("ID del Transaccione a eliminar.")]            int nTransaccionesID,            [Service]            [GraphQLDescription("Servicio para operaciones de Transaccione.")]            ITransaccionesService objService        )        {            return await objService.DeleteTransacciones(nTransaccionesID);        }    }}